custom_css:
/* MoodTube × MoonThemes Discord — карточка «Слушает» из Discord */
:root, [data-mt-theme="custom"] {
    --d-bg: #232428; --d-card: #2b2d31; --d-field: #1e1f22; --d-press: #35373c; --d-line: #3f4147;
    --d-text: #f2f3f5; --d-normal: #dbdee1; --d-muted: #b5bac1; --d-dim: #949ba4;
    --d-blurple: #5865f2; --d-blurple-press: #4752c4; --d-red: #f23f43;

    --mt-slider-track: #4e5058;
    --mt-slider-track-height: 4px;
    --mt-slider-track-radius: 4px;
    --mt-slider-thumb-size: 12px;
    --mt-slider-thumb-radius: 50%;
    --mt-slider-thumb-bg: #ffffff;
    --mt-slider-thumb-bg-hover: #ffffff;
    --mt-slider-thumb-border: none;
    --mt-slider-thumb-shadow: 0 1px 4px rgba(0, 0, 0, 0.5);
    --mt-slider-progress: #ffffff;

    --mt-overlay: rgba(0, 0, 0, 0.6);
    --mt-modal-shadow: 0 8px 32px rgba(0, 0, 0, 0.55);
    --mt-dock-cover-radius: 8px;
    --mt-pl-spotify-tab: var(--d-blurple);
    --mt-pl-spotify-tab-text: #fff;
}

/* ===== Окно плеера ===== */
.mt-player {
    background: var(--d-bg);
    border: none;
    border-radius: 16px;
    box-shadow: 0 8px 28px rgba(0, 0, 0, 0.55);
    backdrop-filter: none; -webkit-backdrop-filter: none;
    padding: 40px 16px 16px;
    color: var(--d-normal);
}
.mt-player-header { top: 14px; left: 16px; align-items: center; }
.mt-player-header-title { color: var(--d-muted); font-size: 11px; font-weight: 800; letter-spacing: 0.04em; text-transform: uppercase; }
.mt-player-status { color: var(--d-dim); font-size: 11px; opacity: 1; }
.mt-player-status::before { content: '· '; }
.mt-player .mt-window-btn { top: 11px; color: var(--d-muted); font-size: 14px; transition: color 0.15s ease; }
.mt-player .mt-window-btn:hover, .mt-player .mt-btn-search.mt-is-open, .mt-player .mt-btn-lyrics.mt-is-open { color: var(--d-text) !important; transform: none; }

/* Обложка — квадрат со скруглением, как картинка активности */
.mt-cover { border: none; border-radius: 12px; background: var(--d-field); box-shadow: 0 4px 14px rgba(0, 0, 0, 0.45); }
.mt-cover-img { border-radius: 12px; }
.mt-cover-hole { display: none; }

.mt-track-title { color: var(--d-text); font-size: 15px; font-weight: 700; }
.mt-track-subtitle { color: var(--d-muted); font-size: 12px; font-weight: 500; }
.mt-time { color: var(--d-dim); font-size: 11px; }

/* Кнопки — круглые, «играть» — блюрпл */
.mt-player .mt-btn:hover, .mt-dock .mt-dock-btn:hover { transform: none; }
.mt-controls { gap: 8px; }
.mt-controls .mt-btn {
    width: 36px; height: 36px; box-sizing: border-box; border-radius: 50%;
    display: inline-flex; align-items: center; justify-content: center;
    background: var(--d-card); color: var(--d-normal); font-size: 14px;
    transition: background-color 0.15s ease;
}
.mt-controls .mt-btn:hover { background: var(--d-press); color: var(--d-text); }
.mt-controls .mt-btn:active { transform: scale(0.92); }
.mt-controls .mt-btn-play { width: 46px; height: 46px; background: var(--d-blurple); color: #fff; font-size: 17px; }
.mt-controls .mt-btn-play:hover { background: var(--d-blurple-press); color: #fff; }
.mt-controls .mt-btn-accent { color: var(--d-normal); }
.mt-btn-ai.mt-is-busy { color: var(--d-blurple) !important; }
.mt-btn-favorite { color: var(--d-muted); }
.mt-btn-favorite.mt-is-active { color: var(--d-red); }
.mt-volume-icon { color: var(--d-muted); }

/* Текст песни */
.mt-lyric-line { color: var(--d-normal); }
.mt-lyric-line.mt-is-active { color: var(--d-text); }
.mt-lyrics-message i { color: var(--d-blurple); }

/* ===== Очередь, плейлисты, поиск ===== */
.mt-panel { background: var(--d-bg); }
.mt-panel-title { color: var(--d-text); font-size: 14px; }
.mt-panel .mt-btn { color: var(--d-muted); }
.mt-queue-item { background: transparent; border: none; border-radius: 8px; margin-bottom: 2px; }
.mt-queue-item:hover { background: var(--d-card); }
.mt-queue-item.mt-is-current { background: rgba(88, 101, 242, 0.18); }
.mt-queue-item.mt-is-current .mt-queue-title { color: var(--d-text); }
.mt-queue-title { color: var(--d-muted); }
.mt-queue-now, .mt-queue-add, .mt-pl-section-add { color: var(--d-blurple); }
.mt-queue-thumb, .mt-pl-cover { border-radius: 6px; }
.mt-pl-section-title { color: var(--d-dim); }
.mt-pl-cover-fav { background: var(--d-blurple); color: #fff; }
.mt-pl-tabs { gap: 6px; }
.mt-pl-tab, .mt-pl-tool, .mt-pl-inline-ok, .mt-pl-inline-cancel { border: none; border-radius: 999px; background: var(--d-card); color: var(--d-normal); }
.mt-pl-tab.mt-is-active, .mt-pl-tab[data-mt-tab="spotify"].mt-is-active, .mt-pl-tool.mt-pl-play, .mt-pl-inline-ok { background: var(--d-blurple); color: #fff; }
.mt-panel-search { background: var(--d-bg) !important; }
#moodtube-search-container #moodtube-search-input { border-radius: 999px !important; border: none !important; background: var(--d-field) !important; color: var(--d-text) !important; }
#moodtube-search-container #moodtube-search-go { border-radius: 50% !important; background: var(--d-blurple) !important; color: #fff !important; }

/* Окно «Добавить в плейлист» */
.mt-pl-modal-box { border: none; border-radius: 16px; background: var(--d-bg); }
.mt-pl-modal-header { color: var(--d-text); }
.mt-pl-modal-close { color: var(--d-muted); }
.mt-pl-option { border-radius: 8px; }
.mt-pl-option:hover { background: var(--d-card); }
.mt-pl-option.mt-is-added .mt-pl-option-icon { color: var(--d-blurple); }

/* ===== Плавающая кнопка ===== */
.mt-fab { border: none; border-radius: 50%; background: var(--d-blurple); color: #fff; box-shadow: 0 4px 14px rgba(0, 0, 0, 0.45); }
#moodtube-fab.mt-playing::before { border-top-color: #fff; }

/* ===== Шапка сверху ===== */
.mt-dock { background: var(--d-bg); border-bottom: 1px solid rgba(0, 0, 0, 0.3); box-shadow: none; backdrop-filter: none; -webkit-backdrop-filter: none; color: var(--d-normal); }
.mt-dock-title { color: var(--d-text); font-size: 13px; font-weight: 700; }
.mt-dock-subtitle { color: var(--d-muted); font-size: 11px; }
.mt-dock-btn { width: 30px; height: 30px; border-radius: 50%; display: inline-flex; align-items: center; justify-content: center; background: var(--d-card); color: var(--d-normal); font-size: 12px; }
.mt-dock-play { background: var(--d-blurple); color: #fff; }
.mt-dock-btn:hover { color: var(--d-text); }
.mt-dock-fav.mt-is-active { color: var(--d-red); }
.mt-dock-progress { background: #4e5058; border-radius: 4px; }
/* Раскрытый плеер под полосой */
.mt-player.mt-player-docked { border-top: 1px solid rgba(0, 0, 0, 0.3); border-radius: 0; background: var(--d-bg); box-shadow: none; }
.mt-dock-progress-fill { background: #fff; border-radius: 4px; }

/* ===== Окно настроек — настройки Discord ===== */
#mt-settings-modal .mt-flex-container { background: var(--d-bg); border: none; border-radius: 16px; color: var(--d-normal); }
#mt-settings-modal .mt-header { background: var(--d-bg); border-bottom: 1px solid rgba(0, 0, 0, 0.3); }
#mt-settings-modal .mt-header h3 { color: var(--d-text); font-weight: 800; letter-spacing: 0; }
#mt-settings-modal .mt-header-icon { color: var(--d-blurple); }
#mt-settings-modal .mt-close { color: var(--d-muted); }
#mt-settings-modal .mt-category { background: var(--d-card); border: none; border-radius: 12px; }
#mt-settings-modal .mt-cat-title h4 { color: var(--d-muted); font-size: 12px; font-weight: 800; letter-spacing: 0.04em; text-transform: uppercase; }
#mt-settings-modal .mt-cat-title i:first-child, #mt-settings-modal .mt-chevron { color: var(--d-muted); }
#mt-settings-modal .mt-label { color: var(--d-dim); }
#mt-settings-modal .mt-label-accent { color: var(--d-text); }
#mt-settings-modal .mt-input-field { background: var(--d-field); border: none; border-radius: 10px; color: var(--d-text); }
#mt-settings-modal .mt-input-field:focus { box-shadow: 0 0 0 2px var(--d-blurple); }
#mt-settings-modal .mt-btn-test, #mt-settings-modal .mt-btn-save { border: none; border-radius: 999px; background: var(--d-press); color: var(--d-text); font-weight: 700; }
#mt-settings-modal .mt-btn-save { background: var(--d-blurple); color: #fff; }
#mt-settings-modal .mt-tag, #mt-settings-modal .mt-catalog-filter { border: none; border-radius: 999px; background: var(--d-press); color: var(--d-normal); }
#mt-settings-modal .mt-tag.active, #mt-settings-modal .mt-catalog-filter.mt-is-active, #mt-settings-modal .mt-summary-tag { background: var(--d-blurple); color: #fff; }
#mt-settings-modal .mt-footer { background: var(--d-bg); border-top: 1px solid rgba(0, 0, 0, 0.3); }
#mt-settings-modal .mt-subpanel, #mt-settings-modal .mt-catalog-card { background: var(--d-field); border: none; border-radius: 12px; }
#mt-settings-modal .mt-divider { border-top: 1px solid var(--d-line); }
#mt-settings-modal code { background: var(--d-field); border-radius: 4px; }
#mt-settings-modal .mt-content::-webkit-scrollbar, .mt-panel-list::-webkit-scrollbar { width: 4px; }
#mt-settings-modal .mt-content::-webkit-scrollbar-thumb, .mt-panel-list::-webkit-scrollbar-thumb { background: #3a3a41; border-radius: 4px; }
